-- Marketplace operations: seller onboarding, admin lifecycle, verified reviews.
-- Applied to the connected Supabase project as well.
create or replace function public.submit_seller_application(p_store_name text,p_description text,p_phone text,p_email text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_user uuid:=auth.uid(); v_id uuid; begin if v_user is null then raise exception 'Not authenticated'; end if; if length(trim(coalesce(p_store_name,'')))<2 then raise exception 'Store name is required'; end if; if exists(select 1 from sellers where owner_id=v_user) then raise exception 'A seller application already exists for this account'; end if; insert into sellers(owner_id,store_name,slug,description,phone,email,status,commission_rate) values(v_user,trim(p_store_name),lower(regexp_replace(trim(p_store_name),'[^a-zA-Z0-9]+','-','g'))||'-'||substr(v_user::text,1,8),nullif(trim(p_description),''),nullif(trim(p_phone),''),nullif(lower(trim(p_email)),''),'pending',10) returning id into v_id; insert into notifications(user_id,title,message,type,data) values(v_user,'Seller application received','Your seller application has been submitted and is awaiting review.','seller_application',jsonb_build_object('seller_id',v_id)); return jsonb_build_object('success',true,'seller_id',v_id); end $$; revoke all on function public.submit_seller_application(text,text,text,text) from public; grant execute on function public.submit_seller_application(text,text,text,text) to authenticated;

create or replace function public.admin_set_seller_status(p_seller_id uuid,p_status text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_owner uuid; begin if not private.is_admin() then raise exception 'Admin access required'; end if; if p_status not in ('pending','active','suspended','rejected') then raise exception 'Invalid seller status'; end if; select owner_id into v_owner from sellers where id=p_seller_id for update; if v_owner is null then raise exception 'Seller not found'; end if; update sellers set status=p_status::seller_status,updated_at=now() where id=p_seller_id; if p_status='active' then update profiles set role='seller',updated_at=now() where id=v_owner; elsif p_status='rejected' then update profiles set role='customer',updated_at=now() where id=v_owner; end if; insert into notifications(user_id,title,message,type,data) values(v_owner,'Seller application updated','Your seller account status is now '||p_status||'.','seller_status',jsonb_build_object('seller_id',p_seller_id,'status',p_status)); insert into audit_logs(actor_id,action,entity_type,entity_id,new_data) values(auth.uid(),'seller_status_updated','seller',p_seller_id,jsonb_build_object('status',p_status)); return jsonb_build_object('success',true); end $$; revoke all on function public.admin_set_seller_status(uuid,text) from public; grant execute on function public.admin_set_seller_status(uuid,text) to authenticated;

create or replace function public.admin_set_order_status(p_order_id uuid,p_status text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_customer uuid; v_old order_status; begin if not private.is_admin() then raise exception 'Admin access required'; end if; if p_status not in ('pending','confirmed','processing','shipped','out_for_delivery','delivered','cancelled','refunded') then raise exception 'Invalid order status'; end if; select customer_id,status into v_customer,v_old from orders where id=p_order_id for update; if v_customer is null then raise exception 'Order not found'; end if; update orders set status=p_status::order_status,updated_at=now() where id=p_order_id; if p_status='delivered' then update shipments set status='delivered',delivered_at=coalesce(delivered_at,now()),updated_at=now() where order_id=p_order_id; elsif p_status='shipped' then update shipments set status='shipped',shipped_at=coalesce(shipped_at,now()),updated_at=now() where order_id=p_order_id; end if; insert into notifications(user_id,title,message,type,data) values(v_customer,'Order status updated','Your order status is now '||replace(p_status,'_',' ')||'.','order_status',jsonb_build_object('order_id',p_order_id,'status',p_status)); insert into audit_logs(actor_id,action,entity_type,entity_id,old_data,new_data) values(auth.uid(),'order_status_updated','order',p_order_id,jsonb_build_object('status',v_old),jsonb_build_object('status',p_status)); return jsonb_build_object('success',true); end $$; revoke all on function public.admin_set_order_status(uuid,text) from public; grant execute on function public.admin_set_order_status(uuid,text) to authenticated;

create or replace function public.submit_product_review(p_product_id uuid,p_order_item_id uuid,p_rating integer,p_title text,p_body text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_user uuid:=auth.uid(); v_order uuid; v_status order_status; v_review uuid; begin if v_user is null then raise exception 'Not authenticated'; end if; if p_rating<1 or p_rating>5 then raise exception 'Rating must be between 1 and 5'; end if; select oi.order_id,o.status into v_order,v_status from order_items oi join orders o on o.id=oi.order_id where oi.id=p_order_item_id and oi.product_id=p_product_id and o.customer_id=v_user; if v_order is null then raise exception 'Purchase not found'; end if; if v_status<>'delivered' then raise exception 'Reviews are available after delivery'; end if; insert into reviews(product_id,customer_id,order_item_id,rating,title,body,is_verified_purchase,is_published) values(p_product_id,v_user,p_order_item_id,p_rating,nullif(trim(p_title),''),nullif(trim(p_body),''),true,true) on conflict(customer_id,product_id,order_item_id) do update set rating=excluded.rating,title=excluded.title,body=excluded.body,is_published=true,updated_at=now() returning id into v_review; update products p set rating_average=coalesce((select avg(r.rating) from reviews r where r.product_id=p.id and r.is_published),0),review_count=(select count(*) from reviews r where r.product_id=p.id and r.is_published),updated_at=now() where p.id=p_product_id; return jsonb_build_object('success',true,'review_id',v_review); end $$; revoke all on function public.submit_product_review(uuid,uuid,integer,text,text) from public; grant execute on function public.submit_product_review(uuid,uuid,integer,text,text) to authenticated;